import copy

class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        prev_move = message.message[0].data[0]
        grid = message.message[0].data[1]
        N = len(grid)

        # Define helper function to find possible values for a cell
        def possible_values(grid_local, r, c):
            if grid_local[r][c] != 0:
                return set()
            used = set()
            # Check row
            for j in range(N):
                if grid_local[r][j] != 0:
                    used.add(grid_local[r][j])
            # Check column
            for i in range(N):
                if grid_local[i][c] != 0:
                    used.add(grid_local[i][c])
            # Check subgrid
            S = int(math.sqrt(N))
            start_row = (r // S) * S
            start_col = (c // S) * S
            for i in range(start_row, start_row + S):
                for j in range(start_col, start_col + S):
                    if grid_local[i][j] != 0:
                        used.add(grid_local[i][j])
            all_nums = set(range(1, N + 1))
            return all_nums - used

        # Define helper function to get allowed cells based on previous move
        def get_allowed_cells(grid_local, prev_move_local):
            if prev_move_local is None:
                return [(i, j) for i in range(N) for j in range(N) if grid_local[i][j] == 0]
            else:
                last_pos = prev_move_local[0]
                last_row, last_col = last_pos
                same_row = [(last_row, j) for j in range(N) if grid_local[last_row][j] == 0]
                same_col = [(i, last_col) for i in range(N) if grid_local[i][last_col] == 0]
                allowed_cells = set(same_row + same_col)
                if not allowed_cells:
                    return [(i, j) for i in range(N) for j in range(N) if grid_local[i][j] == 0]
                else:
                    return list(allowed_cells)

        # Define helper function to get opponent's playable cells after my move
        def get_opp_playable_cells(new_grid, my_row, my_col):
            same_row_empty = [(my_row, j) for j in range(N) if new_grid[my_row][j] == 0]
            same_col_empty = [(i, my_col) for i in range(N) if new_grid[i][my_col] == 0]
            opp_cells_set = set(same_row_empty + same_col_empty)
            if not opp_cells_set:
                return [(i, j) for i in range(N) for j in range(N) if new_grid[i][j] == 0]
            else:
                return list(opp_cells_set)

        # Get my allowed cells
        my_allowed_cells = get_allowed_cells(grid, prev_move)

        # Find all possible moves for me: list of ((r, c), val)
        my_possible_moves = []
        for r, c in my_allowed_cells:
            poss_vals = possible_values(grid, r, c)
            for val in poss_vals:
                my_possible_moves.append(((r, c), val))

        if not my_possible_moves:
            # No valid moves, return an arbitrary move (will likely be invalid and cause loss)
            if my_allowed_cells:
                r, c = my_allowed_cells[0]
                val = 1  # Arbitrary value
            else:
                r, c = 0, 0  # Fallback, might not be empty
                val = 1
            my_move = [(r, c), val]
        else:
            # Check for a winning move that forces opponent into no valid moves
            for move in my_possible_moves:
                pos, val = move
                move_row, move_col = pos
                # Simulate the move
                new_grid_sim = copy.deepcopy(grid)
                new_grid_sim[move_row][move_col] = val
                # Get opponent's playable cells
                opp_playable_cells = get_opp_playable_cells(new_grid_sim, move_row, move_col)
                # Check if all opponent's playable cells have no possible values
                all_opp_invalid = True
                for opp_r, opp_c in opp_playable_cells:
                    opp_poss = possible_values(new_grid_sim, opp_r, opp_c)
                    if opp_poss:
                        all_opp_invalid = False
                        break
                if all_opp_invalid:
                    # This is a winning move, return it
                    my_move = [pos, val]
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=my_move, type='custom')]
                    )

            # No winning move, use fallback: choose cell with minimal possible values and a value
            min_poss_count = float('inf')
            best_cell = None
            best_val_set = set()
            for r, c in my_allowed_cells:
                poss_vals = possible_values(grid, r, c)
                if poss_vals and len(poss_vals) < min_poss_count:
                    min_poss_count = len(poss_vals)
                    best_cell = (r, c)
                    best_val_set = poss_vals
            # Choose the best cell and a value (smallest for determinism)
            if best_cell:
                val = min(best_val_set)
                my_move = [best_cell, val]
            else:
                # This should not happen if my_possible_moves is not empty, but safeguard
                r, c, val = 0, 0, 1  # Arbitrary
                my_move = [(r, c), val]

        # Return the move
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=my_move, type='custom')]
        )

