        else:
            row, col = last_pos
            empty_in_row = [(row, c) for c in range(N) if grid[row][c] == 0]
            empty_in_col = [(r, col) for r in range(N) if grid[r][col] == 0]
            candidates = list(set(empty_in_row + empty_in_col))
            if len(candidates) > 0:
                return candidates
            else:
                return [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]

    def get_possible_values(self, grid, pos):
        N = len(grid)
        sN = int(math.sqrt(N))
        row, col = pos
        if grid[row][col] != 0:
            return []
        row_values = set(grid[row])
        col_values = set(grid[r][col] for r in range(N))
        sub_row_start = (row // sN) * sN
        sub_col_start = (col // sN) * sN
        subgrid_values = set()
        for i in range(sN):
            for j in range(sN):
                subgrid_values.add(grid[sub_row_start + i][sub_col_start + j])
        forbidden = (row_values | col_values | subgrid_values) - {0}
        possible = set(range(1, N + 1)) - forbidden
        return list(possible)

    def has_legal_move(self, grid, last_pos):
        N = len(grid)
        sN = int(math.sqrt(N))
        allowed_pos = self.get_allowed_positions(grid, last_pos)
        for pos in allowed_pos:
            poss_vals = self.get_possible_values(grid, pos)
            if len(poss_vals) > 0:
                return True
        return False

    def receive_message(self, message: Info) -> Info:
        prev_move = message.message[0].data[0]
        grid = message.message[0].data[1]
        N = len(grid)
        sN = int(math.sqrt(N))
        last_pos = None if prev_move is None else prev_move[0]
        my_allowed_pos = self.get_allowed_positions(grid, last_pos)
        for pos in my_allowed_pos:
            poss_vals = self.get_possible_values(grid, pos)
            for val in poss_vals:
                new_grid = [row[:] for row in grid]
                new_grid[pos[0]][pos[1]] = val
                if not self.has_legal_move(new_grid, pos):
                    move = [pos, val]
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=move, type='custom')]
                    )
        # No winning move, choose any legal move
        for pos in my_allowed_pos:
            poss_vals = self.get_possible_values(grid, pos)
            if len(poss_vals) > 0:
                val = poss_vals[0]
