import copy

class SudoKillCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.Custom  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        prev_move = message.message[0].data[0]  
        grid = message.message[0].data[1]  

        # Determine last position for allowed cells
        last_pos = prev_move[0] if prev_move is not None else None  
        allowed_cells = self.get_allowed_cells(grid, last_pos)  

        # Find all possible moves (cell and number) that are legal
        possible_moves = []  
        for cell in allowed_cells:  
            row, col = cell  
            if self.can_place_any(grid, row, col):  
                possible_nums = self.get_possible_nums(grid, row, col)  
                for num in possible_nums:  
                    possible_moves.append((cell, num))  

        # Look for a winning move where opponent has no legal move after my move
        for move in possible_moves:  
            cell, num = move  
            # Simulate the move
            new_grid = copy.deepcopy(grid)  
            new_grid[cell[0]][cell[1]] = num  
            new_last_pos = cell  # My move position becomes the last position
            if not self.has_legal_move(new_grid, new_last_pos):  
                # This move wins, return it
                chosen_move = [cell, num]  
                return Info(  
                    sender=self.__class__.__name__,  
                    receiver=message.sender,  
                    difficulty=message.difficulty,  
                    message=[BaseMessageDataType(data=chosen_move, type='custom')]  
                )  

        # If no winning move, choose any legal move if available
        if possible_moves:  
            cell, num = possible_moves[0]  # Choose the first possible move
            chosen_move = [cell, num]  
        else:  
            # No legal moves available, fallback to an arbitrary move (may violate rules)
            # This should be rare if the game is played legally
            if allowed_cells:  
                cell = allowed_cells[0]  # Choose the first allowed cell
                chosen_move = [cell, 1]  # Place an arbitrary number, e.g., 1
            else:  
                # No empty cells or allowed cells, should not happen, return invalid move
                chosen_move = [(0, 0), 1]  # Arbitrary invalid move as fallback

        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=chosen_move, type='custom')]  
        )  

    def get_allowed_cells(self, grid, last_pos):  
        N = len(grid)  
        if last_pos is None:  
            return [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]  
        else:  
            last_row, last_col = last_pos  
            empty_in_row = [(last_row, c) for c in range(N) if grid[last_row][c] == 0]  
            empty_in_col = [(r, last_col) for r in range(N) if grid[r][last_col] == 0]  
            cells_set = set(empty_in_row + empty_in_col)  
            if len(cells_set) > 0:  
                return list(cells_set)  
            else:  
                return [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]  

    def get_possible_nums(self, grid, row, col):  
        N = len(grid)  
        S = int(math.sqrt(N))  
        row_set = {num for num in grid[row] if num != 0}  
        col_set = {grid[r][col] for r in range(N) if grid[r][col] != 0}  
        start_row = (row // S) * S  
        start_col = (col // S) * S  
        subgrid_set = {grid[i][j] for i in range(start_row, start_row + S) for j in range(start_col, start_col + S) if grid[i][j] != 0}  
        used_numbers = row_set | col_set | subgrid_set  
        possible_nums = [num for num in range(1, N + 1) if num not in used_numbers]  
        return possible_nums  

